import requests
from pathlib import Path
import zipfile
# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    if not isinstance(url, str) or not isinstance(filename, str) or not url or not filename:
        return ("Error: Invalid URL or filename", [])

    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
        file_path = DOWNLOAD_DIR / filename

        with open(file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        extracted_files = []
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            extracted_files = [str(ZIP_DIR / name) for name in zip_ref.namelist()]

        return ("Success", extracted_files)
    except requests.RequestException as e:
        return (f"Error: Failed to download the file: {e}", [])
    except (zipfile.BadZipFile, IOError) as e:
        return (f"Error: Failed to extract the file: {e}", [])

